const cfg = $('Config').first().json;
const norm = s => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const rand = (a, b) => { if (b < a) b = a; return Math.floor(Math.random() * (b - a + 1)) + a; };
const num = (v, def) => { const n = Number(v); return Number.isFinite(n) ? n : def; };
const HORA_INI = num(cfg.horaInicio, 9);
const HORA_FIM = Math.max(num(cfg.horaFim, 18), HORA_INI + 1);
const DIAS_MAX = num(cfg.diasMax, 2);
const GAP_MIN = num(cfg.intervaloMinSeg, 120);
const GAP_MAX = Math.max(num(cfg.intervaloMaxSeg, 420), GAP_MIN);
const TESTE_INT = num(cfg.testeIntervaloSeg, 20);
const LIMITE_TESTE = num(cfg.limiteTeste, 1);
const DIAS_RETRO = num(cfg.diasRetroativos, 3);
const dataDe = r => new Date(r.end_date ?? r.start_date ?? r.arrived ?? NaN);

// ---------- 1) Normaliza a resposta da API (array, {data:[]}, {attendances:[]}) ----------
let registros = [];
for (const it of $input.all()) {
  const j = it.json;
  if (Array.isArray(j)) registros.push(...j);
  else if (Array.isArray(j.data)) registros.push(...j.data);
  else if (Array.isArray(j.attendances)) registros.push(...j.attendances);
  else if (Array.isArray(j.items)) registros.push(...j.items);
  else registros.push(j);
}

// ---------- 2) Filtra status "Finalizado" e sinônimos ----------
const SINONIMOS = ['finalizad', 'conclu', 'realizad', 'atendid', 'encerrad', 'completed', 'finished', 'done', 'closed'];
const EXCLUIR   = ['nao ', 'não', 'cancel', 'falt', 'pendente', 'aguard', 'andamento'];
const statusDe = r => norm(r?.status?.name ?? r?.status?.label ?? r?.status ?? r?.situacao ?? '');

let finalizados = registros.filter(r => {
  // AmigoApp: flags booleanas
  if (r.canceled === true || r.missed === true) return false;
  if (typeof r.done === 'boolean') return r.done === true;
  // fallback: status em texto, caso exista
  const st = statusDe(r);
  if (!st) return false;
  if (EXCLUIR.some(e => st.startsWith(norm(e)) || st.includes(norm(e)))) return false;
  return SINONIMOS.some(s => st.includes(s));
});

// ---------- 3) Evita reenvio (guarda IDs já programados) ----------
const sd = $getWorkflowStaticData('global');
sd.enviados = sd.enviados || [];
sd.ultimaMsg = sd.ultimaMsg ?? -1;
const idDe = r => String(r.id ?? r._id ?? r.attendanceId ?? '');
const TESTE = cfg.modoTeste === true || String(cfg.modoTeste).toLowerCase() === 'true';
if (!TESTE) {
  finalizados = finalizados.filter(r => idDe(r) && !sd.enviados.includes(idDe(r)));
  if (DIAS_RETRO > 0) finalizados = finalizados.filter(r => { const d = dataDe(r); return !isNaN(d) && (Date.now() - d.getTime()) <= DIAS_RETRO * 86400000; });
}
if (TESTE) {
  finalizados = finalizados.slice(0, LIMITE_TESTE || 1);
  // sem nenhuma consulta finalizada na API? cria um registro fictício para testar o envio
  if (!finalizados.length) finalizados = [{ id: 'teste-' + Date.now(), name: 'Teste' }];
}

// ---------- 4) 10 modelos de mensagem (sorteio sem repetir o anterior) ----------
const link = cfg.linkFormulario && cfg.linkFormulario.trim() ? cfg.linkFormulario.trim() : '{{LINK_DO_FORMULARIO}}';
const MODELOS = [
  n => `Olá, ${n}! 😊 Tudo bem? Foi um prazer te atender. Sua opinião é muito importante para nós! Poderia responder nossa pesquisa de satisfação? Leva menos de 2 minutos:\n\n${link}`,
  n => `Oi, ${n}! Esperamos que você esteja bem. Gostaríamos de saber como foi sua experiência na consulta. Pode nos ajudar respondendo esta pesquisa rápida?\n\n${link}`,
  n => `${n}, tudo certo? 👋 Queremos melhorar cada vez mais o nosso atendimento e, para isso, precisamos da sua avaliação. Responda aqui, por favor:\n\n${link}`,
  n => `Olá, ${n}! Agradecemos por confiar no nosso cuidado. 💙 Conte pra gente como foi sua consulta, é rapidinho:\n\n${link}`,
  n => `Oi, ${n}! Passando para saber como foi sua experiência com a gente. Sua resposta nos ajuda a evoluir! Acesse a pesquisa:\n\n${link}`,
  n => `Olá, ${n}, como você está? Sua consulta foi concluída e queremos ouvir você! Que tal avaliar o nosso atendimento? ⭐\n\n${link}`,
  n => `${n}, obrigado(a) por escolher a nossa clínica! 🙏 Poderia dedicar um minutinho para responder nossa pesquisa de satisfação?\n\n${link}`,
  n => `Oi, ${n}! A sua opinião faz toda a diferença para a nossa equipe. Conta pra gente: como foi seu atendimento?\n\n${link}`,
  n => `Olá, ${n}! 😀 Esperamos que tenha gostado do atendimento. Para continuarmos melhorando, responda nossa breve pesquisa:\n\n${link}`,
  n => `${n}, tudo bem? Nosso objetivo é cuidar bem de você, e seu feedback é essencial. Poderia nos avaliar por aqui?\n\n${link}`,
];
const sortearModelo = () => {
  let i; do { i = rand(0, MODELOS.length - 1); } while (i === sd.ultimaMsg && MODELOS.length > 1);
  sd.ultimaMsg = i; return i;
};

// ---------- 5) Telefone e nome ----------
const nomeDe = r => {
  const full = r.patient?.name ?? r.paciente?.nome ?? r.patientName ?? r.contact?.name ?? r.customer?.name ?? r.name ?? r.nome ?? 'paciente';
  const p = String(full).trim().split(/\s+/)[0];
  return p.charAt(0).toUpperCase() + p.slice(1).toLowerCase();
};
const telDe = r => {
  const p = r.patient ?? {};
  let t = String(p.contact_cellphone ?? p.cellphone ?? p.phone ?? p.contact_phone ?? r.phone ?? r.telefone ?? r.contact?.phone ?? r.whatsapp ?? '').replace(/\D/g, '');
  const dial = String(p.contact_cellphone_dial_code ?? '55').replace(/\D/g, '') || '55';
  if (t.length === 10 || t.length === 11) t = dial + t;
  return t;
};

// ---------- 6) Sorteio de dia/horário + intervalo mínimo entre envios ----------
const agora = new Date();
const itens = [];
for (const r of finalizados) {
  const numero = TESTE ? String(cfg.numeroTeste).replace(/\D/g, '') : telDe(r);
  if (numero.length < 12) continue; // telefone inválido
  const d = new Date(agora);
  if (TESTE) {
    d.setTime(agora.getTime() + (itens.length * TESTE_INT + rand(5, 15)) * 1000);
  } else {
    d.setDate(d.getDate() + rand(0, DIAS_MAX));
    d.setHours(rand(HORA_INI, HORA_FIM - 1), rand(0, 59), rand(0, 59), 0);
    if (d < agora) d.setTime(agora.getTime() + rand(60, 600) * 1000);
  }
  const nome = nomeDe(r);
  itens.push({ id: idDe(r), nome, numero, dataEnvio: d, mensagem: (TESTE ? '[TESTE] ' : '') + MODELOS[sortearModelo()](nome) });
}
itens.sort((a, b) => a.dataEnvio - b.dataEnvio);

// intervalo aleatório mínimo entre um paciente e outro
for (let i = 1; i < itens.length && !TESTE; i++) {
  const gap = rand(GAP_MIN, GAP_MAX) * 1000;
  if (itens[i].dataEnvio - itens[i - 1].dataEnvio < gap) {
    itens[i].dataEnvio = new Date(itens[i - 1].dataEnvio.getTime() + gap);
  }
}

if (!TESTE) {
  itens.forEach(i => sd.enviados.push(i.id));
  sd.enviados = sd.enviados.slice(-5000);
}

return itens.map(i => ({ json: { id: i.id, nome: i.nome, numero: i.numero, mensagem: i.mensagem, sendAt: (isNaN(i.dataEnvio.getTime()) ? new Date(Date.now() + 60000) : i.dataEnvio).toISOString() } }));

const RANK = { ERROR: 0, PENDING: 1, SERVER_ACK: 2, DELIVERY_ACK: 3, READ: 4, PLAYED: 5 };
const ctx = $('Loop Over Items').first().json;

let erro = '';
let regs = [];
const coletar = (o, d = 0) => {
  if (!o || d > 6) return;
  if (Array.isArray(o)) { o.forEach(v => coletar(v, d + 1)); return; }
  if (typeof o !== 'object') return;
  if (o.error && !o.status) { erro = o.error.message ?? String(o.error); return; }
  const st = String(o.status ?? o.message_status ?? '').toUpperCase();
  if (st in RANK) regs.push({ status: st });
  for (const k of Object.keys(o)) if (o[k] && typeof o[k] === 'object') coletar(o[k], d + 1);
};
const bruto = $input.all().map(i => i.json);
coletar(bruto);

const semConf = !!erro && !regs.length;
let melhor = 'PENDING';
for (const r of regs) {
  const s = String(r.status ?? r.message_status ?? '').toUpperCase();
  if (s in RANK && RANK[s] >= RANK[melhor]) melhor = s;
}
if (regs.some(r => String(r.status ?? '').toUpperCase() === 'ERROR')) melhor = 'ERROR';

let tentativa = 1;
try { const prev = $('Interpretar status').first().json; if (prev && prev.id === ctx.id) tentativa = (prev.tentativa || 0) + 1; } catch (e) {}

return [{ json: {
  id: ctx.id, nome: ctx.nome, numero: ctx.numero,
  message_status: semConf ? 'SEM_CONFIRMACAO' : melhor,
  erro,
  tentativa,
  debug_consulta: JSON.stringify(bruto).slice(0, 400),
  enviadoOk: !semConf && RANK[melhor] >= RANK.SERVER_ACK,       // chegou nos servidores do WhatsApp
  entregue: !semConf && RANK[melhor] >= RANK.DELIVERY_ACK,       // entregue/lida
  verificadoEm: new Date().toISOString(),
}}];
